 1→{"entry_id": 873520, "headword": "الرائد", "headword_norm": "الرائد", "root": "رد", "root_source": "camel", "pos": null, "definitions_text": "(الرائد) من يتَقَدَّم الْقَوْم يبصر لَهُم الْكلأ ومساقط الْغَيْث وَفِي الْمثل (الرائد لَا يكذب أَهله) للَّذي لَا يكذب إِذا حدث وَمن رجال الْجَيْش والشرطة ضَابِط رتبته فَوق النَّقِيب وَدون الْمُقدم (محدثة) (ج) رواد ورادة ورائد الْعين القذى (ج) روائد وَيُقَال فلَان رائد الوساد إِذا لم يسْتَقرّ من مرض أَو هم وَهِي رائدة وَيُقَال امْرَأَة رائدة طوافة فِي بيُوت جاراتها", "dict_name_ar": "المعجم الوسيط لمجموعة من المؤلفين", "source_type": "hawramani", "period": "modern"}
 2→{"entry_id": 11820, "headword": "الرَّائِدُ", "headword_norm": "الرائد", "root": "رود", "root_source": "ocr", "pos": "noun", "definitions_text": "من يتقدَّم القوم يبصر لهم الكلأَ ومساقط الغيث من رجال الجيش والشرطة: ضابط رتبته فوق النقيب ودون المقدم. (محدثة) رائد العين: القذى", "dict_name_ar": "المعجم الوسيط", "source_type": "ocr", "period": "modern"}
 3→{"entry_id": 91225, "headword": "الرَّائد", "headword_norm": "الرائد", "root": "رأد", "root_source": "ocr", "pos": "noun", "definitions_text": "رائدُ الضُّحى: انْبِساطُ شَمْسِه, وارتفاعُ نهاره", "dict_name_ar": "المعجم الكبير", "source_type": "ocr", "period": "modern"}
 4→{"entry_id": 40223, "headword": "الرَّائِد", "headword_norm": "الرائد", "root": "رود", "root_source": "ocr", "pos": "noun", "definitions_text": "الذى يتقدم القوم يبصر لهم مواضع الكلأ, ومساقط الغيث من يقدم - غير مسبوق - على عمل فيمهد الطريق لمن بعده كرائد الفضاء استعاره النابغة للسابق إلى ما يكسب الحمد والثناء", "dict_name_ar": "المعجم الكبير", "source_type": "ocr", "period": "modern"}
 5→{"entry_id": 40224, "headword": "الرَّائِد", "headword_norm": "الرائد", "root": "رود", "root_source": "ocr", "pos": "noun", "definitions_text": "الغيث: النبت العود الذي تدار به الرحى, وهو مقبضها. يقال: أدار الرحى بالرائد الرسول مقدمة الشيء؛ وفي الخبر: الحمى رائد الموت أي مقدمته؛ لشدتها على التشبيه الذي يتقدم بمكروه الذي لا منزل له الجاسوس أول رتبة عسكرية في سلم رتب ضباط قادة في الجيش والشرطة. وتقع بين رتبتي نقيب ومقدم", "dict_name_ar": "المعجم الكبير", "source_type": "ocr", "period": "modern"}
 6→{"entry_id": 819826, "headword": "السّابق", "headword_norm": "السابق", "root": "سبق", "root_source": "camel", "pos": null, "definitions_text": "السّابق:[في الانكليزية] Predecessor [ في الفرنسية] Predecesseur عند المحدّثين هو أحد الراويين المشتركين في الرواية عن شيخ الذي تقدّم موته على الراوي الآخر إلى أن يكون بين وفاتيهما تباعد شديد، فحصل بينهما أمر بعيد، وذلك الراوي الآخر الذي تأخّر موته يسمّى لاحقا. وفائدة ذلك الاعتبار الأمن من ظنّ سقوط شيء في إسناد المتأخّر وتفقّه الطالب في معرفة العالي والنّازل، كذا في شرح النخبة وشرحه.", "dict_name_ar": "كشّاف اصطلاحات الفنون والعلوم للتهانوي", "source_type": "hawramani", "period": "classical"}
 7→{"entry_id": 874923, "headword": "السَّابِق", "headword_norm": "السابق", "root": "سبق", "root_source": "camel", "pos": null, "definitions_text": "(السَّابِق) الْمُتَقَدّم فِي الْخَيْر وَفِي التَّنْزِيل الْعَزِيز {وَالسَّابِقُونَ السَّابِقُونَ أُولَئِكَ المقربون}", "dict_name_ar": "المعجم الوسيط لمجموعة من المؤلفين", "source_type": "hawramani", "period": "modern"}
 8→{"entry_id": 12931, "headword": "السَّابِقُ", "headword_norm": "السابق", "root": "سبق", "root_source": "ocr", "pos": "noun", "definitions_text": "المتقدّم في الخير", "dict_name_ar": "المعجم الوسيط", "source_type": "ocr", "period": "modern"}
 9→{"entry_id": 44193, "headword": "السَّابِقُ", "headword_norm": "السابق", "root": "سبق", "root_source": "ocr", "pos": "noun", "definitions_text": "المتقدِّمُ في الخَيْر", "dict_name_ar": "المعجم الكبير", "source_type": "ocr", "period": "modern"}
10→{"entry_id": 968594, "headword": "السَّلِفُ", "headword_norm": "السلف", "root": "سلف", "root_source": "camel", "pos": null, "definitions_text": "السَّلِفُ:\nبفتح أوّله، وكسر ثانيه، بوزن الصّدف، وقيل: السّلف بوزن صرد: وهما قبيلتان قديمتان من قبائل اليمن، قال هشام بن محمد ولد يقطن، وقيل: يقطان بن عامر بن شالخ بن أرفخشد بن سام ابن نوح الموذاذ، وسالف وهم السلف، وهو الذي نصب دمشق وحضرموت، وقد سمي بالسلف مخلاف باليمن، والسلف والسلك: من أولاد الحجل، والسّلف من الأرض جمع سلفة: وهي الكردة المسوّاة.", "dict_name_ar": "معجم البلدان لياقوت الحموي", "source_type": "hawramani", "period": "classical"}
11→{"entry_id": 807044, "headword": "السَّلَفُ", "headword_norm": "السلف", "root": "سلف", "root_source": "camel", "pos": null, "definitions_text": "السَّلَفُ: كَذَلِك.", "dict_name_ar": "معجم مقاليد العلوم للسيوطي", "source_type": "hawramani", "period": "classical"}
12→{"entry_id": 814100, "headword": "السلف", "headword_norm": "السلف", "root": "سلف", "root_source": "camel", "pos": null, "definitions_text": "السلف: التقدم، ولزيد سلف كريم أي آباء متقدمون جمعه أسلاف.", "dict_name_ar": "التوقيف على مهمات التعاريف للمناوي", "source_type": "hawramani", "period": "classical"}
13→{"entry_id": 819893, "headword": "السّلف", "headword_norm": "السلف", "root": "سلف", "root_source": "camel", "pos": null, "definitions_text": "السّلف:[في الانكليزية] Ancestors ،old ،ancients ،predecessors [ في الفرنسية] Ancetres ،anciens ،predecesseurs \nبالفتح في اللّغة: الموت، والآباء المتوفّون، والسبق والقدماء وبيع السّلم كما في المنتخب. وفي شرح المنهاج السّلف والسّلم بمعنى والسّلم لغة أهل الحجاز والسّلف لغة أهل العراق. وفي جامع الرموز في كتاب الشهادة السّلف في الشرع اسم لكلّ من يقلّد مذهبه في الدين ويتبع أثره كأبي حنيفة وأصحابه فإنّهم سلف لنا والصحابة والتابعين فإنّهم سلفهم. وقد يطلق السّلف شاملا للمجتهدين كلّهم انتهى. وفي كليات أبي البقاء السّلف محركة السّلم اسم من الأسلاف والقرض الذي لا منفعة فيه للمقرض، وعلى المقترض ردّه كما أخذ. وكلّ عمل صالح قدمته وكلّ من تقدّمك من آبائك وقرابتك فهو سلف وفرط لك.والسّلف من أبي حنيفة إلى محمد بن الحسن، والخلف من محمد بن الحسن إلى شمس الأئمة الحلواني، والمتأخرون من شمس الأئمة الحلواني إلى حافظ الدين البخاري.والمتقدمون في لساننا أبو حنيفة وتلاميذه بلا واسطة، والمتأخرون هم الذين بعدهم من المجتهدين في المذهب. وقال بعضهم السّلف شرعا كل من يقلّد ويقتفى أثره في الدين كأبي حنيفة وأصحابه فإنهم سلفنا، وأما الصحابة فإنهم سلفهم وأبو حنيفة من أجلاء التابعين.", "dict_name_ar": "كشّاف اصطلاحات الفنون والعلوم للتهانوي", "source_type": "hawramani", "period": "classical"}
14→{"entry_id": 834877, "headword": "السَّلَف", "headword_norm": "السلف", "root": "سلف", "root_source": "camel", "pos": null, "definitions_text": "السَّلَف: محركةً اسمٌ لكل من يُقلَّد مذهبه ويُتَّبع أثره، كالإمام أبي حنيفة وغيرِهم من الأئمة وأصحابهم رحمهم الله، فإنهم سلف لنا، وكالصحابة والتابعين فإنهم سلف لهم ويقابله الخَلَف. وقد يطلق السلفُ شاملاً للمجتهدين كلِّهم من الصحابة والتابعين وأتباعهم إلى المائة الرابعة، ومَن كانوا بعد المائة الرابعة فهم خلف. وأيضاً السَّلَف بمعنى السَّلَم في لغة أهل الحجاز مرَّ في بيع السَّلَم، وأيضاً يطلق على القرض.", "dict_name_ar": "التعريفات الفقهيّة للبركتي", "source_type": "hawramani", "period": "modern"}
15→{"entry_id": 875500, "headword": "السّلف", "headword_norm": "السلف", "root": "سلف", "root_source": "camel", "pos": null, "definitions_text": "(السّلف) الْجلد لم يحكم دبغه والجراب الضخم (ج) أسلف وسلوف\n(السّلف) للرجل زوج أُخْت امْرَأَته وهما سلفان والأسلوفة وغرلة الصَّبِي (ج) أسلاف\n(السّلف) جمع سالف وكل مَا تقدمك من آبَائِك وَذَوي قرابتك فِي السن أَو الْفضل وكل عمل صَالح قَدمته وَمَا قدم من الثّمن على الْمَبِيع و (فِي الْمُعَامَلَات) الْقَرْض الَّذِي لَا مَنْفَعَة للمقرض فِيهِ وَبيع السّلم (ج) أسلاف وسلاف\n(السّلف) السّلف وغرلة الصَّبِي (ج) أسلاف\n(السّلف) فرخ الحجل وفرخ القطاة (ج) سلفان", "dict_name_ar": "المعجم الوسيط لمجموعة من المؤلفين", "source_type": "hawramani", "period": "modern"}
16→{"entry_id": 816811, "headword": "السّلف", "headword_norm": "السلف", "root": "سلف", "root_source": "camel", "pos": null, "definitions_text": "السّلف: كل من تقدم من الْآبَاء والأقرباء. وَعند الْفُقَهَاء هم من أبي حنيفَة رَحمَه الله تَعَالَى إِلَى مُحَمَّد بن الْحسن وَالْخلف من مُحَمَّد بن الْحسن إِلَى شمس الْأَئِمَّة الحلوائي والمتأخرون من شمس الْأَئِمَّة الحلوائي إِلَى مَوْلَانَا حَافظ الدّين البُخَارِيّ هَكَذَا ذكره صَاحب الخيالات اللطيفة فِي الْهَامِش.", "dict_name_ar": "دستور العلماء للأحمدنكري", "source_type": "hawramani", "period": "classical"}
