29→{"entry_id": 925404, "headword": "رَائِد", "headword_norm": "رائد", "root": "رد", "root_source": "camel", "pos": null, "definitions_text": "رَائِد\nمن (ر و د) الرسول، ومن يتقدم القوم يبصر لهم الكلأ ومساقط الغيث، وضابط فوق النقيب ودون المقدم.", "dict_name_ar": "موسوعة السلطان قابوس لأسماء العرب", "source_type": "hawramani", "period": "classical"}
