31→{"entry_id": 895262, "headword": "سَابق", "headword_norm": "سابق", "root": "سبق", "root_source": "camel", "pos": null, "definitions_text": "(سَابق) إِلَى الشَّيْء مسابقة وسباقا أسْرع إِلَيْهِ وَفِي التَّنْزِيل الْعَزِيز {سابقوا إِلَى مغْفرَة من ربكُم} وَبَين الْخَيل أرسلها وَعَلَيْهَا فرسانها لينْظر أَيهَا بسبق وَفُلَانًا جاراه وباراه", "dict_name_ar": "المعجم الوسيط لمجموعة من المؤلفين", "source_type": "hawramani", "period": "modern"}
32→{"entry_id": 927655, "headword": "سَابِق", "headword_norm": "سابق", "root": "سبق", "root_source": "camel", "pos": null, "definitions_text": "سَابِق\nمن (س ب ق) المتقدم في الخير ومن يعلو على قومه في الكرم، والفرس الذي يجيء قبل غيره.", "dict_name_ar": "موسوعة السلطان قابوس لأسماء العرب", "source_type": "hawramani", "period": "classical"}
33→{"entry_id": 12927, "headword": "سابق", "headword_norm": "سابق", "root": "سبق", "root_source": "ocr", "pos": "verb", "definitions_text": "إلى الشيء مسابقة , وسباقاً : أسرع إليه بين الخيل : أرسلها وعليها فرسانها لينظر أيها يسبق فلاناً : جاراه باراه", "dict_name_ar": "المعجم الوسيط", "source_type": "ocr", "period": "modern"}
34→{"entry_id": 44185, "headword": "سابَقَ", "headword_norm": "سابق", "root": "سبق", "root_source": "ocr", "pos": "verb", "definitions_text": "سابَقَ فلانٌ إلى الشىء: أَسْرع إليه سابَقَ بين الخيل: أرْسلها وعليها فرسانُها لينظرَ أيُّها يَسْبِق سابَقَ فلانًا, وغيرَه: جاراه وباراه. يقال: سابقه فَسَبَقه", "dict_name_ar": "المعجم الكبير", "source_type": "ocr", "period": "modern"}
35→{"entry_id": 44192, "headword": "سابِق", "headword_norm": "سابق", "root": "سبق", "root_source": "ocr", "pos": "proper_noun", "definitions_text": "عَلَمٌ على غير واحد, منهم: سابق بن عبد الله البرقىّ المعروف بالبَرْبَرىّ, من موالى بنى أمية: شاعر من الزُّهَّاد, له أشعار حَسَنَة فى الحِكْمَة والرقائق", "dict_name_ar": "المعجم الكبير", "source_type": "ocr", "period": "modern"}
36→{"entry_id": 44181, "headword": "سَابِق", "headword_norm": "سابق", "root": "سبق", "root_source": "ocr", "pos": "adj", "definitions_text": "من يتقدم في الجري أو الكرم أو غير ذلك", "dict_name_ar": "المعجم الكبير", "source_type": "ocr", "period": "modern"}
37→{"entry_id": 838017, "headword": "سلف", "headword_norm": "سلف", "root": "سلف", "root_source": "camel", "pos": null, "definitions_text": "باب السين واللام والفاء معهما س ل ف، ف ل س، ف س ل، س ف ل مستعملات\nسلف: أسلفته مالاً: أقرضته، والسلف من القرض. والسَّلَفُ: كلُّ شيءٍ قَدَّمْتَه فهو سَلَفٌ، والفعل سَلَفَ يسلُفُ سُلُوفاً. والقومُ إذا أرادوا أن يَنْفِروا فمن تقَدَّم من نَفيرهم فسَبَقَ فهو سَلَفٌ لهم، قال:\nنحن منعنا منبت النَّصِيِّ ... بسَلَفٍ أَرعَنَ عَنْبَريِّ \nوالسُّلْفَةُ: ما يَتَسَلَّفُ الرجلُ فيأكُلُ قبل غَدائه. والأُمَم السالفة الماضية أمام الغابرة، قال:\nولاقَتْ مناياها القُرونُ السَّوالِفُ ... كذلك تَلقاها القرون الخوالِف \nأي يموت من بقِيَ كما ماتَ من مَضَى. والسالِفةُ: أعلى العُنُق. [وسالِفة الفرس وغيرها: هاديتُه، أي ما تقدَّمَ من عُنُقه]  . والسَّلْفُ: جِرابٌ ضَخُم، والجميع سلوف. وسُلافَةُ كُلِّ شيءٍ: خُلاصَتُه. والسَّلِفُ  : غُرْلة الصَّبيِّ. والسُّلْفانُ: أولاد الحَجَل واحدها سُلَفٌ. والسُّلفةُ: الطعامُ يُتَعَلَّلُ به قبل الغداء  ، وكذلك اللُّهْنةُ، وقد سَلَّفْتُهم. والمُسْلِفُ من النِّساء: التي بلغت خمساً وأربعين ونحوَها. والسُّلفةُ: جِلُدٌ رقيقٌ يُجعَل بِطانةً للخِفاف أحمرَ وأصفَرَ والسَّلُوف من نِصال السِّهام: ما طال [وأنشد:\nشَكَّ كُلاها بسَلوفٍ سَنْدَريُّ] \nوسَلَفُتُ الأرض بالمِسْلَفةِ إذا سَوَّيْتُها للزرع، وأرض مَسلوفةٌ أي مستوية. والسِّلْفانِ: رجلانِ تَزَوَّجا بأختَيْنِ، [وكلُّ واحدٍ منهما سِلْفٌ لصاحبه]  ، والمرأة سلفة لصاحبتها [إذا تزوَّجَت أختانِ بأخَوْينِ]  . والسُّلافة من الخمر أفضَلُها يَتَحلَّبُ من غير عَصْرٍ ولا مرث. وهذا سَلِفي وأنا سَلِفُه.\nفلس: وأفلس الرجل إذا صار ذا فُلُوس بعد الدراهم [والفَلْسُ معروف، وجمعُه فلوسٌ]  . [وقد فَلَّسه الحاكمُ تفليساً]  . والتَفليسُ في اللون إذا كان على جِلده لُمَعٌ كالفُلوس، ودابَّة مُفَلِّس: فيها لُمَعٌ كالفلوس. والفَلْسُ: خاتَم من رَصاصٍ يُختَم به عُنُقَ من يعطى الجِزْية.\nفسل: الفَسْلُ: الرَّذْل النَّذْل الذي لا مُروءةَ له ولا جَلَد، وفَسُلَ فَسالة. والفَسيل: صِغارُ النَّخل، والواحدة بالهاء. وفُسالة الحديد: ما تَناثَر منه عند الضرب إذا طُبعَ.\nسفل: وأسفَلُ وأعلَى، وسُفْلٌ وعُلْو، وتسفل وتَعَلىَّ، وسافلةٌ وعاليةٌ، وسُفلَى وعُليا، وسَفال وعَلاء، وسفوُل وعُلُوّ نقائض. وسِفْلةٌ وعِليةُ وسفلة.", "dict_name_ar": "كتاب العين للخليل بن أحمد الفراهيدي", "source_type": "hawramani", "period": "classical"}
38→{"entry_id": 911562, "headword": "سلف", "headword_norm": "سلف", "root": "سلف", "root_source": "camel", "pos": null, "definitions_text": "سلف وَقَالَ أَبُو عبيد: فِي حَدِيث عبيد أَرض الْجنَّة مسلوفة. قَالَ الْأَصْمَعِي: هِيَ المستوية أَو المُسَوَّاةُ - شكّ أَبُو عبيد قَالَ: وَهَذِه لُغَة أهل الْيمن والطائف وَتلك النَّاحِيَة يَقُولُونَ سَلَفْتُ الأرْض أسْلُفُها وَيُقَال للحجر الَّذِي تُسوِّى بِهِ الأَرْض: مِسْلَفَةٌ. وَقَالَ أَبُو عبيد: وَأَحْسبهُ حجرا مُدْمَجاً يُدحرج بِهِ على الأَرْض لتستوي.", "dict_name_ar": "غريب الحديث لأبي عبيد القاسم بن سلام", "source_type": "hawramani", "period": "classical"}
39→{"entry_id": 981683, "headword": "سلف", "headword_norm": "سلف", "root": "سلف", "root_source": "camel", "pos": null, "definitions_text": "[سلف] سَلَفْتُ الأرضَ أَسْلُفُها سَلْفاً، إذا سويتها بالمسلفة، وهى شئ تُسَوَّى به الأرض. وفي حديث عبيد بن عمير: \" أرضُ الجنةِ مسلوفةٌ \" قال الأصمعي: هي المستوية أو المُسَوَّاة وسَلَفَ يَسْلُفُ سَلَفاً، مثال طلب يطلب طلبا، أي مضى. والقومُ السُلاَّفُ: المتقدِّمون. وسَلَفُ الرجل: آباؤه المتقدّمون، والجمع أَسْلافٌ وسُلاَّفٌ. والسَلَفُ: نوعٌ من البيوع يعجل فيه الثمن وتضبط السلعةُ بالوصف إلى أجلٍ معلومٍ. وقد أَسْلَفْتُ في كذا. واسْتَسْلَفْتُ منه دراهم وتَسَلَّفْتُ، وأَسْلَفَني. والسَلْفُ، بالتسكين: الجِرابَ الضخمُ. والسُلْفَةُ بالضم: ما يتعجَّله الرجل من الطعام قبل الغَداء. تقول منه: سَلَّفْتُ الرجل تَسْليفاً. والتَسْليفُ أيضاً: التقديمُ. وسَلِفُ الرجلِ: زوجُ أختِ امرأتِه وكذلك سلفه، مثال كذب وكذب، وكبد وكبد. والمسلف من النساء: التي بلغت خَمساً وأربعين أو نَحوها، وهو وصفٌ خُصَّ به الاناث. قال الشاعر : فيها ثلاث كالدمى وكاعب ومسلف  والسالفة: ناحية مقدَّم العنق من لدن مُعَلَّق القرطِ إلى قَلْتِ التَرقوةِ. والسالِفُ والسليف: المتقدم. والسلوف: النافة تكون في أوائل الإبل إذا وردت الماء. والسُلافُ: ما سال من عصير العنب قبل أن يُعْصَرَ. وتُسَمَّى الخمرُ سُلافاً. وسُلافَةُ كلِّ شئ عصرته: أوله. والسلفان: أولاد الحجل، الواحد سلف مثل صرد وصردان . قال أبو عمرو: ولم نسمع سلفة للانثى، ولو قيل سلفة كما قيل سلكة لواحدة السلكان لكان جيدا. قال الشاعر : أُعالِجُ سِلْفاناً صِغاراً تَخالُهُمْ إذا درجوا بجر الحواصل حمرا وقال آخر:\nخطفنه خطف القطامى السلف", "dict_name_ar": "تاج اللغة وصِحاح العربية للجوهري", "source_type": "hawramani", "period": "classical"}
40→{"entry_id": 986997, "headword": "سَلَفَ ", "headword_norm": "سلف", "root": "سلف", "root_source": "camel", "pos": null, "definitions_text": "(سَلَفَ) السِّينُ وَاللَّامُ وَالْفَاءُ أَصْلٌ يَدُلُّ عَلَى تَقَدُّمٍ وَسَبْقٍ. مِنْ ذَلِكَ السَّلَفُ: الَّذِينَ مَضَوْا. وَالْقَوْمُ السُّلَّافُ: الْمُتَقَدِّمُونَ. وَالسُّلَافُ: السَّائِلُ مِنْ عَصِيرِ الْعِنَبِ قَبْلَ أَنْ يُعْصَرَ. وَالسُّلْفَةُ: الْمُعَجَّلُ مِنَ الطَّعَامِ قَبْلَ الْغَدَاءِ. وَالسُّلُوفُ: النَّاقَةُ تَكُونُ فِي أَوَائِلِ الْإِبِلِ إِذَا وَرَدَتْ. وَمِنَ الْبَابِ السَّلَفُ فِي الْبَيْعِ، وَهُوَ مَالٌ يُقَدَّمُ لِمَا يُشْتَرَى نَسَاءً. وَنَاسٌ يُسَمُّونَ الْقَرْضَ السَّلَفَ، وَهُوَ ذَاكَ الْقِيَاسُ لِأَنَّهُ شَيْءٌ يُقَدَّمُ بِعِوَضٍ يَتَأَخَّرُ. وَمِنْ غَيْرِ هَذَا الْقِيَاسِ السِّلْفُ سِلْفُ الرِّجَالِ، وَهُمَا اللَّذَانِ يَتَزَوَّجُ هَذَا أُخْتًا وَهَذَا أُخْتًا. وَهَذَا قِيَاسُ السَّالِفَتَيْنِ، وَهُمَا صَفْحَتَا الْعُنُقِ، هَذِهِ بِحِذَاءِ هَذِهِ.\nوَمِمَّا شَذَّ عَنِ الْبَابَيْنِ السَّلْفُ وَهُوَ الْجِرَابُ. وَيُقَالُ إِنَّ الْقُلْفَةَ تُسَمَّى سَلْفًا. وَمِنْهُ أَسْلَفْتُ الْأَرْضَ لِلزَّرْعِ، إِذَا سَوَّيْتَهَا. وَمُمْكِنٌ أَنْ يَكُونَ هَذَا مِنْ قِيَاسِ الْبَابِ الْأَوَّلِ: لِأَنَّهُ أَمْرٌ قَدْ تَقَدَّمَ فِي إِصْلَاحِهِ.", "dict_name_ar": "مقاييس اللغة لابن فارس", "source_type": "hawramani", "period": "classical"}
